#!/usr/bin/env bash
# Mesh-rendered showcase videos: N long test prompts (distinct objects) generated by RetHOI, plus the
# ground truth, rendered as SMPL + object meshes and tiled into a grid (assets/comparison.*).
#   bash scripts/render_showcase.sh [N=6]
set -e
N=${1:-6}
mkdir -p logs results renders/{gt,rethoi} assets
J() { local name=$1; shift; sbatch --parsable -J "$name" scripts/slurm_job.sh "$@"; }
GEN="python -W ignore -m sample.generate_eval --guidance --seed 10 --showcase $N --batch_size $N"

g1=$(J show_rethoi  $GEN --model_path save/rethoi/model000020000.pt  --afford_model_path save/apdm_con/model000010000.pt  --out results/showcase_rethoi.npz)

deps=()
for ((i = 0; i < N; i++)); do
  deps+=($(sbatch --parsable -J r_rethoi$i  --dependency=afterok:$g1 scripts/slurm_job.sh python -W ignore -m visualize.render_hoi --samples results/showcase_rethoi.npz  --indices $i --out_dir renders/rethoi))
  deps+=($(sbatch --parsable -J r_gt$i      --dependency=afterok:$g1 scripts/slurm_job.sh python -W ignore -m visualize.render_hoi --samples results/showcase_rethoi.npz  --indices $i --gt --out_dir renders/gt))
done
dep=$(IFS=:; echo "${deps[*]}")
sbatch --parsable -J grid --dependency=afterok:$dep -p compute --gres=gpu:0 scripts/slurm_job.sh bash -c '
  cols=$(ls renders/rethoi/*.mp4 | wc -l)
  python -m visualize.make_grid --rows "Ground truth" "RetHOI (ours)" --cols $cols \
    --videos $(ls renders/gt/*.mp4) $(ls renders/rethoi/*.mp4) --out assets/comparison.mp4
  python -m visualize.shrink_gif assets/comparison.mp4 assets/comparison.gif 1200 3
  python -m visualize.make_grid --rows "RetHOI (ours)" --cols $cols --videos $(ls renders/rethoi/*.mp4) \
    --out assets/rethoi_samples.mp4
  python -m visualize.shrink_gif assets/rethoi_samples.mp4 assets/rethoi_samples.gif 1400 2'
squeue -u "$USER"
